// Expo config plugin for Play Console "Android vitals" recommendations.
// android/ is regenerated by prebuild, so these edits live here instead.
const { withAppBuildGradle, withAndroidManifest } = require('expo/config-plugins');

module.exports = function withAndroidVitals(config) {
  // R8 optimization: the RN template uses proguard-android.txt, which contains
  // -dontoptimize. The *-optimize* variant lets R8 fully optimize the release DEX.
  config = withAppBuildGradle(config, (c) => {
    c.modResults.contents = c.modResults.contents.replace(
      /getDefaultProguardFile\(\s*["']proguard-android\.txt["']\s*\)/g,
      'getDefaultProguardFile("proguard-android-optimize.txt")'
    );
    return c;
  });

  // Large screens: no orientation lock and resizable on tablets/foldables/ChromeOS.
  config = withAndroidManifest(config, (c) => {
    const app = c.modResults.manifest.application?.[0];
    if (app) {
      app.$['android:resizeableActivity'] = 'true';
      (app.activity || []).forEach((a) => {
        delete a.$['android:screenOrientation'];
        a.$['android:resizeableActivity'] = 'true';
      });
    }
    return c;
  });
  return config;
};
